import{_ as e,c as t,o as s,a4 as a}from"./chunks/framework.P4k6vdAm.js";const f=JSON.parse('{"title":"HTTP Redirect","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/http-redirect.md","filePath":"docs/tasks/http-redirect.md","lastUpdated":1793099931000}'),o={name:"docs/tasks/http-redirect.md"},i=a('<h1 id="http-redirect" tabindex="-1">HTTP Redirect <a class="header-anchor" href="#http-redirect" aria-label="Permalink to &quot;HTTP Redirect&quot;">​</a></h1><p>The HTTP Redirect task forwards the caller to a new page or website after the endpoint completes. For example, you could send the user to a Thank You page after they fill out a survey on your website.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ul><li><strong>Redirect URI</strong> - where the user will be sent after the endpoint completes. This should be a full URL, including the <code>http://</code> or <code>https://</code> prefix. For example: <code>https://www.example.com/surveys/thankyou.html</code></li><li><strong>Body</strong> - a JSON body. In most cases you can simply use an empty object (<code>{}</code>), unless you know that you need to include data here.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The HTTP Redirect task is typically the last task in an endpoint.</li><li>You do not typically need to use this task in addition to the <a href="/docs/tasks/http-response.html">HTTP Response task</a>. If you are using both, set up <a href="/docs/building/working-with-data.html#filters">filters</a> to decide which one is used by the endpoint.</li><li>If an HTTP Redirect task runs, the caller is redirected regardless of any other task&#39;s status code. See <a href="/docs/building/endpoint-response.html">How the Endpoint Response is Decided</a>.</li></ul>',6),r=[i];function d(n,l,c,h,p,u){return s(),t("div",null,r)}const m=e(o,[["render",d]]);export{f as __pageData,m as default};
